// Monta o pedido para o gestão: o banco cria as 7 tarefas do onboarding (a regra de prazos e responsáveis está na função srv_onboarding_arco).
const d = $('Escolhe card').first().json;
const link = $('Provisiona no portal').first().json;
const cfg = $('Config').first().json;
const rodape = `Pasta do cliente: dentro de ARCO no Drive (https://drive.google.com/drive/folders/19AC0X4Q25SluBrujiwDEgumBUa2VFkrP), criada pela rotina de rascunhos.\nCriada automaticamente pelo fluxo de onboarding (contrato: ${d.nome_documento}).` + (d.card_id ? `\nCard no CRM: ${d.card_id}` : '') + (link.cliente_id ? `\nPortal: ${cfg.PORTAL_URL}/admin/cliente/${link.cliente_id}` : '');
return [{ json: { cliente: d.cliente, rodape } }];
